   204                      } else {
   205                          val = JS_ToObject(ctx, this_obj);
   206                          if (JS_IsException(val))
   207                              goto exception;
   208                      }
   209                  } else {
   210                  normal_this:
   211                      val = JS_DupValue(ctx, this_obj);
   212                  }
   213                  *sp++ = val;
   214              }
